134	  // Org JSON file-watcher: re-seed registry + departments into SQLite when the
135	  // source-of-truth files at ~/.claude/org/ change on disk. Lets users edit
136	  // registry.json or departments.json directly and see the org chart update
137	  // within a few seconds — no server restart required.
138	  try {
139	    const chokidar = require('chokidar');
140	    const orgLib = require('./org');
141	    const ORG_DIR = path.dirname(orgLib.REGISTRY_PATH);
142	    const DEPTS_PATH = path.join(ORG_DIR, 'departments.json');
143	
144	    // Boot-time load: ensure SQLite departments + agent fields reflect
145	    // whatever's currently on disk. Without this, edits made while the
146	    // server was stopped won't propagate (the migration v4/v5 importers
147	    // only run on schema bumps, not regular startups).
148	    try {
149	      if (fs.existsSync(DEPTS_PATH)) {
150	        const parsed = JSON.parse(fs.readFileSync(DEPTS_PATH, 'utf-8'));
151	        db.saveDepartments(parsed);
152	        console.log(`  OrgWatch: bootstrapped departments.json into SQLite (version ${parsed.version || '?'})`);
153	      }
154	      if (fs.existsSync(orgLib.REGISTRY_PATH)) {
155	        const reg = JSON.parse(fs.readFileSync(orgLib.REGISTRY_PATH, 'utf-8'));
156	        if (reg.agents) {
157	          // Patch agent dept/subDept/pod/secondaryReportsTo + tags/squad
158	          // for every agent already known to SQLite. This mirrors the v4/v5
159	          // migration logic but runs every boot for resilience.
160	          const sqlitedb = db.getDb();
161	          const updateStmt = sqlitedb.prepare(
162	            'UPDATE agents SET department=?, subDepartment=?, pod=?, secondaryReportsTo=? WHERE id=?'
163	          );
164	          let touched = 0;
165	          for (const [id, a] of Object.entries(reg.agents)) {
166	            try {
167	              updateStmt.run(
168	                a.department || null,
169	                a.subDepartment || null,
170	                a.pod || null,
171	                a.secondaryReportsTo || null,
172	                id,
173	              );
174	              touched += 1;
175	            } catch { /* row may not exist yet — agentSync.reseedFromDisk will INSERT */ }
176	          }
177	          console.log(`  OrgWatch: bootstrapped registry.json fields into SQLite (${touched} agents touched, version ${reg.version || '?'})`);
178	        }
179	      }
180	    } catch (err) {
181	      console.warn(`  OrgWatch: bootstrap load failed: ${err.message}`);
182	    }
183	
184	    const orgWatcher = chokidar.watch([
185	      orgLib.REGISTRY_PATH,
186	      DEPTS_PATH,
187	    ], { ignoreInitial: true, awaitWriteFinish: { stabilityThreshold: 400, pollInterval: 100 } });
188	    let reseedTimer = null;
189	    const queueReseed = (filePath) => {
190	      // Debounce — multiple writes in the same atomic-rename burst trigger
191	      // a single reseed.
192	      if (reseedTimer) clearTimeout(reseedTimer);
193	      reseedTimer = setTimeout(() => {
194	        const baseName = path.basename(filePath);
195	        try {
196	          // Bug 9 fix: when departments.json changes, push the new content
197	          // into SQLite (db.loadDepartments reads from SQLite, not the JSON
198	          // file). Without this, edits to ~/.claude/org/departments.json are
199	          // silently ignored by the running server.
200	          if (baseName === 'departments.json') {
201	            const fileContent = fs.readFileSync(DEPTS_PATH, 'utf-8');
202	            const parsed = JSON.parse(fileContent);
203	            db.saveDepartments(parsed);
204	            console.log(`[org-watch] departments.json reloaded into SQLite (${Object.keys(parsed.departments || {}).length} depts, version ${parsed.version})`);
205	          }
206	          // Reseed agent .md files into SQLite (registry.json edits propagate
207	          // through this path too, since the registry is rebuilt from .md
208	          // frontmatter on every reseed).
209	          const sum = agentSync.reseedFromDisk();
210	          console.log(`[org-watch] ${baseName} changed → reseeded ${sum.upserted}/${sum.scanned}`);
211	          agentSync.events.emit('taxonomy:update', { ts: Date.now(), reason: 'org-files-changed', file: baseName });
212	        } catch (err) {
213	          console.warn(`[org-watch] reseed failed: ${err.message}`);
214	        }
215	      }, 500);
216	    };
217	    orgWatcher.on('change', queueReseed);
218	    orgWatcher.on('add', queueReseed);
219	    console.log('  OrgWatch: chokidar watching registry.json + departments.json');
220	  } catch (err) {
221	    console.log(`  OrgWatch: failed to start — ${err.message}`);
222	  }
223	
224	  // Auto-backup SQLite data on startup + every 6 hours
225	  try { db.autoBackupToFile(); } catch {}
226	  setInterval(() => { try { db.autoBackupToFile(); } catch {} }, 6 * 60 * 60 * 1000);
227	
228	  // ── HR cron jobs ──────────────────────────────────────────────────────────
229	  // Roster nightly recompute (02:00 UTC) — refreshes experience profiles
230	  // Witness daily sweep (03:00 UTC) — classifies yesterday's runs
231	  // Cadence weekly review (Monday 09:00 UTC) — applies promotions + PIPs
232	  try {
233	    cron.schedule('0 2 * * *', () => {
234	      try {
235	        const summary = experience.recomputeAllExperience(org);
