237	      } catch (err) {
238	        console.warn(`[HR] Roster recompute failed: ${err.message}`);
239	      }
240	    }, { timezone: 'Etc/UTC' });
241	
242	    cron.schedule('0 3 * * *', () => {
243	      try {
244	        const recent = loadRecentAgentRuns(24);
245	        const result = hr.runWitnessSweep(org, experience, recent);
246	        console.log(`[HR] Witness sweep: ${result.runsClassified} runs, ${result.pipCandidates.length} PIP, ${result.promotionCandidates.length} promo`);
247	      } catch (err) {
248	        console.warn(`[HR] Witness sweep failed: ${err.message}`);
249	      }
250	
251	      // Sprint 5 — auto-advance any open escalation past its tier SLA
252	      // (24h specialist → pod-lead → vp → yash). Runs alongside Witness so
253	      // SLA breaches surface in the same daily ops digest.
254	      try {
255	        const escalation = require('./lib/escalation');
256	        const advanced = escalation.autoAdvanceExpired();
257	        if (advanced.length > 0) {
258	          console.log(`[HR] Escalation SLA sweep: advanced ${advanced.length} stale escalation(s)`);
259	        }
260	      } catch (err) {
261	        console.warn(`[HR] Escalation SLA sweep failed: ${err.message}`);
262	      }
263	
264	      // Phase B — reconcile per-agent active_task_count against the tasks
265	      // table in case any state got dropped (crashed mid-transaction etc.).
266	      // Cheap UPDATE — runs in a single statement.
267	      try {
268	        const tasks = require('./lib/tasks');
269	        tasks.reconcileLoad();
270	      } catch (err) {
271	        console.warn(`[HR] Task load reconcile failed: ${err.message}`);
272	      }
273	    }, { timezone: 'Etc/UTC' });
274	
275	    cron.schedule('0 9 * * 1', () => {
276	      try {
277	        const recent = loadRecentAgentRuns(24 * 7);
278	        const review = hr.runCadenceReview(org, experience, recent);
279	        console.log(`[HR] Cadence weekly review ${review.week}: ${review.promotions.length} promotions, ${review.pipsOpened.length} PIPs`);
280	      } catch (err) {
281	        console.warn(`[HR] Cadence review failed: ${err.message}`);
282	      }
283	    }, { timezone: 'Etc/UTC' });
284	
285	    console.log('  HR: cron jobs scheduled (Roster 02:00, Witness 03:00, Cadence Mon 09:00 UTC)');
286	  } catch (err) {
287	    console.warn(`  HR: cron scheduling failed — ${err.message}`);
288	  }
289	
290	  console.log('');
291	});
