3	const fs = require('fs');
4	const path = require('path');
5	const os = require('os');
6	const { readFileSafe } = require('./atomicIo');
7	const { listAgents } = require('./cache');
8	
9	const HOME = os.homedir();
10	
11	function listMdFiles(dir) {
12	  try {
13	    if (!fs.existsSync(dir)) return [];
14	    return fs.readdirSync(dir)
15	      .filter(f => f.endsWith('.md'))
16	      .map(f => {
17	        const filePath = path.join(dir, f);
18	        const content = readFileSafe(filePath);
19	        const stats = fs.statSync(filePath);
20	        return {
21	          name: f.replace('.md', ''),
22	          content: content || '',
23	          path: filePath,
24	          updatedAt: stats.mtime.toISOString(),
25	        };
26	      });
27	  } catch {
28	    return [];
29	  }
30	}
31	
32	function discoverProjects(dirs) {
33	  const projects = [];
34	  for (const dir of dirs) {
35	    const resolved = dir.replace(/^~/, HOME);
36	    if (!fs.existsSync(resolved)) continue;
37	    try {
38	      const entries = fs.readdirSync(resolved, { withFileTypes: true });
39	      for (const entry of entries) {
40	        if (!entry.isDirectory()) continue;
41	        if (entry.name.startsWith('.') || entry.name === 'node_modules') continue;
42	        const projectPath = path.join(resolved, entry.name);
43	        const hasClaudeDir = fs.existsSync(path.join(projectPath, '.claude'));
44	        const hasClaudeMd = fs.existsSync(path.join(projectPath, 'CLAUDE.md'));
45	        const hasPackageJson = fs.existsSync(path.join(projectPath, 'package.json'));
46	        const hasPubspec = fs.existsSync(path.join(projectPath, 'pubspec.yaml'));
47	        if (hasClaudeDir || hasClaudeMd || hasPackageJson || hasPubspec) {
48	          const agents = listAgents(path.join(projectPath, '.claude', 'agents'));
49	          const commands = listMdFiles(path.join(projectPath, '.claude', 'commands'));
50	          const rules = listMdFiles(path.join(projectPath, '.claude', 'rules'));
51	          projects.push({
52	            id: Buffer.from(projectPath).toString('base64url'),
53	            name: entry.name,
54	            path: projectPath,
55	            displayPath: projectPath.replace(HOME, '~'),
56	            hasClaudeDir,
57	            hasClaudeMd,
58	            agentCount: agents.length,
59	            commandCount: commands.length,
60	            ruleCount: rules.length,
61	            agents,
62	            commands: commands.map(c => c.name),
63	            rules: rules.map(r => r.name),
64	          });
65	        }
66	      }
67	    } catch {}
68	  }
69	  return projects;
70	}
71	
72	module.exports = { discoverProjects, listMdFiles };
