1	// ── SQLite Database Module for Polyglot ──────────────────────────────────────
2	// Replaces JSON file storage with a local SQLite database.
3	// Uses better-sqlite3 (synchronous, fast, no async overhead).
4	// Database file: data/polyglot.db (created automatically on first access).
5	
6	const Database = require('better-sqlite3');
7	const path = require('path');
8	const fs = require('fs');
9	
10	const DB_DIR = path.join(__dirname, '..', 'data');
11	const DB_PATH = path.join(DB_DIR, 'polyglot.db');
12	const HOME = process.env.HOME || process.env.USERPROFILE || '';
13	const ORG_DIR = path.join(HOME, '.claude', 'org');
14	
15	let _db = null;
16	
17	// ── Database Lifecycle ──────────────────────────────────────────────────────
18	
19	function getDb() {
20	  if (_db) return _db;
21	  fs.mkdirSync(DB_DIR, { recursive: true });
22	  _db = new Database(DB_PATH);
23	  _db.pragma('journal_mode = WAL');
24	  _db.pragma('foreign_keys = ON');
25	  _db.pragma('busy_timeout = 5000');
26	  _db.pragma('synchronous = NORMAL');
27	
28	  // Integrity check — catch corruption early
29	  try {
30	    const check = _db.pragma('integrity_check');
31	    if (check[0]?.integrity_check !== 'ok') {
32	      console.error('[db] INTEGRITY CHECK FAILED:', check);
33	    }
34	  } catch (err) {
35	    console.error('[db] Integrity check error:', err.message);
36	  }
37	
38	  runMigrations(_db);
39	  return _db;
40	}
41	
42	function close() {
43	  if (_db) { _db.close(); _db = null; }
44	}
45	
46	// ── Prepared Statement Cache ────────────────────────────────────────────────
47	
48	const _stmts = {};
49	function stmt(sql) {
50	  if (!_stmts[sql]) _stmts[sql] = getDb().prepare(sql);
51	  return _stmts[sql];
52	}
53	
54	// ── Schema Migrations ───────────────────────────────────────────────────────
55	
56	function runMigrations(db) {
57	  db.exec(`CREATE TABLE IF NOT EXISTS schema_migrations (
58	    version INTEGER PRIMARY KEY,
59	    name TEXT NOT NULL,
60	    applied_at TEXT NOT NULL DEFAULT (datetime('now'))
61	  )`);
62	
63	  const applied = new Set(db.prepare('SELECT version FROM schema_migrations').all().map(r => r.version));
64	
65	  const migrations = [
66	    { version: 1, name: 'create_all_tables', fn: createAllTables },
67	    { version: 2, name: 'import_json_data', fn: importJsonData },
68	    { version: 3, name: 'create_change_log', fn: createChangeLog },
69	    { version: 4, name: 'org_structure_v2', fn: orgStructureV2Migration },
70	    { version: 5, name: 'tags_squad_history', fn: tagsSquadHistoryMigration },
71	    { version: 6, name: 'tasks_table', fn: tasksTableMigration },
72	    { version: 7, name: 'agent_capacity_columns', fn: agentCapacityMigration },
73	    { version: 8, name: 'orchestration_runtime', fn: orchestrationRuntimeMigration },
74	    { version: 9, name: 'node_positions', fn: nodePositionsMigration },
75	    { version: 10, name: 'node_positions_locked', fn: nodePositionsLockedMigration },
76	    { version: 11, name: 'agent_avatar', fn: agentAvatarMigration },
77	    { version: 12, name: 'agent_gender', fn: agentGenderMigration },
78	  ];
79	
80	  for (const mig of migrations) {
81	    if (applied.has(mig.version)) continue;
82	    console.log(`[db] Running migration ${mig.version}: ${mig.name}`);
83	    db.transaction(() => {
84	      mig.fn(db);
85	      db.prepare('INSERT INTO schema_migrations (version, name) VALUES (?, ?)').run(mig.version, mig.name);
86	    })();
87	  }
88	}
89	
90	// ── Migration v4: Org Structure v2 (2026-04-27) ────────────────────────────
91	// Adds subDepartment + pod + secondaryReportsTo columns to agents.
92	// Adds sub_departments + replaced_by + deprecated_at columns to departments.
93	// Reimports departments.json + registry.json so existing rows pick up the new
94	// hierarchical fields.
95	function orgStructureV2Migration(db) {
96	  const hasCol = (table, col) => {
97	    return db.prepare(`PRAGMA table_info(${table})`).all().some((c) => c.name === col);
98	  };
99	
100	  // agents — add 3 new columns idempotently
101	  if (!hasCol('agents', 'subDepartment')) db.exec("ALTER TABLE agents ADD COLUMN subDepartment TEXT");
102	  if (!hasCol('agents', 'pod')) db.exec("ALTER TABLE agents ADD COLUMN pod TEXT");
103	  if (!hasCol('agents', 'secondaryReportsTo')) db.exec("ALTER TABLE agents ADD COLUMN secondaryReportsTo TEXT");
104	
105	  // departments — add subDepartments JSON + deprecation tracking
106	  if (!hasCol('departments', 'sub_departments')) db.exec("ALTER TABLE departments ADD COLUMN sub_departments TEXT DEFAULT '{}'");
107	  if (!hasCol('departments', 'replaced_by')) db.exec("ALTER TABLE departments ADD COLUMN replaced_by TEXT");
108	  if (!hasCol('departments', 'deprecated_at')) db.exec("ALTER TABLE departments ADD COLUMN deprecated_at TEXT");
109	
110	  // Indexes for new columns
111	  db.exec("CREATE INDEX IF NOT EXISTS idx_agents_subDepartment ON agents(subDepartment)");
112	  db.exec("CREATE INDEX IF NOT EXISTS idx_agents_pod ON agents(pod)");
113	
114	  // Reimport departments.json (now contains design + content-seo + subDepartments)
115	  const fs = require('fs');
116	  const path = require('path');
117	  const HOME = require('os').homedir();
118	  const ORG_DIR = path.join(HOME, '.claude', 'org');
119	
120	  const deptsFile = path.join(ORG_DIR, 'departments.json');
121	  if (fs.existsSync(deptsFile)) {
122	    try {
123	      const data = JSON.parse(fs.readFileSync(deptsFile, 'utf-8'));
124	      if (data.departments) {
125	        const ds = db.prepare(`INSERT OR REPLACE INTO departments
126	          (id,label,description,head,color,icon,sort_order,active,sub_departments,replaced_by,deprecated_at)
127	          VALUES (?,?,?,?,?,?,?,?,?,?,?)`);
128	        for (const d of Object.values(data.departments)) {
129	          ds.run(
130	            d.id, d.label, d.description, d.head, d.color, d.icon,
131	            d.order || 0,
132	            d.active !== false ? 1 : 0,
133	            JSON.stringify(d.subDepartments || {}),
134	            d.replacedBy ? JSON.stringify(d.replacedBy) : null,
135	            d.deprecatedAt || null,
136	          );
137	        }
