1753	function updateRow(tableName, pkValue, updates) {
1754	  const d = getDb();
1755	  const pkCol = getPrimaryKeyColumn(tableName);
1756	  if (!pkCol) throw new Error(`No primary key found for table ${tableName}`);
1757	
1758	  // Snapshot old data
1759	  const oldRow = d.prepare(`SELECT * FROM "${tableName}" WHERE "${pkCol}" = ?`).get(pkValue);
1760	  if (!oldRow) throw new Error(`Row not found: ${pkCol}=${pkValue}`);
1761	
1762	  // Build UPDATE
1763	  const setClauses = [];
1764	  const values = [];
1765	  for (const [col, val] of Object.entries(updates)) {
1766	    if (col === pkCol) continue; // Don't update PK
1767	    setClauses.push(`"${col}" = ?`);
1768	    values.push(val === undefined ? null : val);
1769	  }
1770	  if (setClauses.length === 0) throw new Error('No fields to update');
1771	
1772	  values.push(pkValue);
1773	  d.prepare(`UPDATE "${tableName}" SET ${setClauses.join(', ')} WHERE "${pkCol}" = ?`).run(...values);
1774	
1775	  // Get new data
1776	  const newRow = d.prepare(`SELECT * FROM "${tableName}" WHERE "${pkCol}" = ?`).get(pkValue);
1777	
1778	  // Log the change
1779	  logChange(tableName, pkValue, 'update', oldRow, newRow);
1780	
1781	  return newRow;
1782	}
